"""Lab ownership manifest and target verification.

A lab target is accepted for mutation only when ALL of these hold:

* a lab manifest generated by ``lab_bootstrap`` exists and parses strictly;
* the origin is exactly ``https://127.0.0.1:<port>`` (loopback literal);
* a running container with the recorded name and ID exists, carries the
  recorded lab label, runs the pinned NiFi image digest and publishes 8443/tcp
  only on 127.0.0.1:<port>;
* the TLS server certificate presented on that origin has the fingerprint
  recorded in the manifest (generated by this lab's private CA).

A URL, an environment variable or a model-supplied argument alone can never
turn an arbitrary NiFi into a lab.
"""
from __future__ import annotations

import hashlib
import json
import re
import socket
import ssl
from pathlib import Path
from urllib.parse import urlsplit

from . import dockerctl

MANIFEST_NAME = "lab-manifest.json"
MANIFEST_SCHEMA = "nifimcp-lab-manifest/1"
LAB_ID_RE = re.compile(r"^lab-[0-9a-f]{12}$")


class LabBoundaryError(RuntimeError):
    """Raised when a target cannot be proven to be an owned disposable lab."""


def load_manifest(lab_dir: Path) -> dict:
    path = Path(lab_dir) / MANIFEST_NAME
    if not path.is_file() or path.is_symlink():
        raise LabBoundaryError("lab manifest not found; run scripts/lab_bootstrap.py --create-owned-lab")
    try:
        manifest = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise LabBoundaryError("lab manifest is unreadable") from exc
    validate_manifest_shape(manifest)
    return manifest


def validate_manifest_shape(manifest: dict) -> None:
    required = {
        "schema": str, "lab_id": str, "origin": str, "container_name": str,
        "container_id": str, "image": dict, "pki": dict, "port": int,
    }
    if not isinstance(manifest, dict):
        raise LabBoundaryError("lab manifest must be an object")
    for key, kind in required.items():
        if not isinstance(manifest.get(key), kind):
            raise LabBoundaryError(f"lab manifest field missing or invalid: {key}")
    if manifest["schema"] != MANIFEST_SCHEMA:
        raise LabBoundaryError("unsupported lab manifest schema")
    if not LAB_ID_RE.fullmatch(manifest["lab_id"]):
        raise LabBoundaryError("invalid lab id")
    if not re.fullmatch(r"[0-9a-f]{64}", manifest["container_id"]):
        raise LabBoundaryError("invalid container id")
    if manifest["container_name"] != "nifimcp-" + manifest["lab_id"]:
        raise LabBoundaryError("container name does not belong to this lab id")
    check_origin(manifest["origin"], manifest["port"])


def check_origin(origin: str, port: int) -> None:
    parts = urlsplit(origin)
    if (
        parts.scheme != "https"
        or parts.hostname != "127.0.0.1"
        or parts.port != port
        or parts.username
        or parts.password
        or parts.path not in ("", "/")
        or parts.query
        or parts.fragment
        or not (1024 <= port <= 65535)
    ):
        raise LabBoundaryError("lab origin must be exactly https://127.0.0.1:<port>")


def peer_fingerprint(origin: str, ca_path: str, timeout: float = 10.0) -> str:
    parts = urlsplit(origin)
    context = ssl.create_default_context(cafile=ca_path)
    context.check_hostname = True
    with socket.create_connection((parts.hostname, parts.port), timeout=timeout) as raw:
        with context.wrap_socket(raw, server_hostname=parts.hostname) as tls:
            der = tls.getpeercert(binary_form=True)
    return hashlib.sha256(der).hexdigest()


def verify_lab_target(manifest: dict, *, check_tls: bool = True) -> dict:
    """Verify container identity and TLS pin. Returns facts used for evidence."""
    validate_manifest_shape(manifest)
    info = dockerctl.inspect_container(manifest["container_name"])
    if info is None:
        raise LabBoundaryError("recorded lab container does not exist")
    if info.get("Id") != manifest["container_id"]:
        raise LabBoundaryError("container ID does not match the lab manifest")
    labels = (info.get("Config") or {}).get("Labels") or {}
    if labels.get(dockerctl.LAB_LABEL) != manifest["lab_id"]:
        raise LabBoundaryError("container is not labelled as this lab")
    if info.get("Image") != dockerctl.NIFI_IMAGE_DIGEST:
        raise LabBoundaryError("container image does not match the pinned NiFi 2.12.0 digest")
    if not (info.get("State") or {}).get("Running"):
        raise LabBoundaryError("lab container is not running")
    bindings = ((info.get("HostConfig") or {}).get("PortBindings") or {}).get("8443/tcp") or []
    if bindings != [{"HostIp": "127.0.0.1", "HostPort": str(manifest["port"])}]:
        raise LabBoundaryError("lab port is not published exclusively on 127.0.0.1")
    facts = {
        "container_id": info["Id"],
        "image": info["Image"],
        "started_at": (info.get("State") or {}).get("StartedAt"),
    }
    if check_tls:
        fp = peer_fingerprint(manifest["origin"], manifest["pki"]["ca_path"])
        if fp != manifest["pki"]["server_fingerprint_sha256"]:
            raise LabBoundaryError("TLS server certificate does not match the lab manifest pin")
        facts["server_fingerprint_sha256"] = fp
    return facts
